package app.local.spark.background;
import android.app.Activity;import android.os.Bundle;import android.widget.*;import org.json.*;import java.io.File;import java.nio.charset.StandardCharsets;import java.nio.file.Files;
/** Reads only this helper's last snapshot; displays freshness explicitly. */
public final class StreakPreviewActivity extends Activity {
 private String selected;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(32,100,32,60);ScrollView scroll=new ScrollView(this);scroll.addView(page);setContentView(scroll);
  add(page,"火花状态预览（上次只读刷新）",23);add(page,"这里是读取时的快照，发送前还需重新刷新。未知、重燃中和已续上的好友不会自动发送。",16);
  try{JSONObject data=new JSONObject(new String(Files.readAllBytes(new File(getFilesDir(),"state-read-private.json").toPath()),StandardCharsets.UTF_8));add(page,"读取时间："+new java.text.SimpleDateFormat("MM-dd HH:mm:ss").format(new java.util.Date(data.getLong("readAt"))),16);RadioGroup group=new RadioGroup(this);page.addView(group);JSONArray rows=data.getJSONArray("conversations");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String name=row.optString("displayName");if(name.isEmpty())name="昵称暂未获取";String state=row.optString("state");RadioButton choice=new RadioButton(this);choice.setText(name+"  ·  "+("pending".equals(state)?"待续":"done".equals(state)?"今天已续":"recover".equals(state)?"重燃中":"inactive".equals(state)?"不活跃":"未知"));choice.setTextSize(18);choice.setPadding(0,12,0,12);choice.setEnabled("pending".equals(state)&&!row.optString("displayName").isEmpty());String id=row.getString("conversationId");choice.setOnCheckedChangeListener((button,checked)->{if(checked)selected=id;});group.addView(choice);}}
  catch(Exception e){add(page,"还没有可预览的结果，请先返回并刷新真实状态。",16);}Button send=new Button(this);send.setText("给选中好友发一个😀测试（先刷新状态）");page.addView(send);send.setOnClickListener(v->{if(selected==null){Toast.makeText(this,"请先选择一位待续好友",Toast.LENGTH_SHORT).show();return;}startForegroundService(new android.content.Intent(this,EngineService.class).putExtra("mode","send").putExtra("conversationId",selected));finish();});Button back=new Button(this);back.setText("返回助手");page.addView(back);back.setOnClickListener(v->finish());
 }
 private void add(LinearLayout page,String text,int size){TextView label=new TextView(this);label.setText(text);label.setTextSize(size);label.setPadding(0,14,0,14);page.addView(label);}
 @Override public void dump(String prefix,java.io.FileDescriptor fd,java.io.PrintWriter out,String[] args){
  if(args.length!=2||!"target".equals(args[0]))return;
  try{JSONObject data=new JSONObject(new String(Files.readAllBytes(new File(getFilesDir(),"state-read-private.json").toPath()),StandardCharsets.UTF_8));JSONArray rows=data.getJSONArray("conversations");JSONObject report=new JSONObject();int matches=0;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(args[1].equalsIgnoreCase(row.optString("displayName"))){matches++;report.put("state",row.optString("state"));JSONObject raw=new JSONObject(row.getString("raw"));JSONArray windows=raw.optJSONArray("flame_infos");double now=System.currentTimeMillis()/1000.0;for(int w=0;windows!=null&&w<windows.length();w++){JSONObject window=windows.getJSONObject(w);if(window.optDouble("start")<=now&&now<window.optDouble("end"))report.put("officialDays",window.has("real_days")?window.opt("real_days"):window.opt("days"));}}}report.put("matches",matches);report.put("snapshotAt",data.getLong("readAt"));out.println("SPARK_TARGET_REPORT "+report.toString());}catch(Exception e){out.println("SPARK_TARGET_REPORT unavailable");}
 }

}
